        '<span class="kw3">① 輪状甲状靱帯切開／穿刺（cricothyrotomy）</span>……'
        '<span class="kw3">甲状軟骨と輪状軟骨の間の膜を切開する。'
        '皮膚のすぐ下にあり、血管も甲状腺もないので最速（数十秒）</span>。'
        '<span class="kw3">緊急用（"cannot intubate, cannot ventilate"）</span>で、'
        '<span class="kw4">長期留置は声門下狭窄を招くので、落ち着いたら気管切開へ移行する</span>。'
