        '<span class="kw4">急性期の有害事象</span>……'
        '<span class="kw4">口腔・咽頭粘膜炎（強い疼痛で経口摂取が困難になる）、'
        '皮膚炎、味覚障害、口腔乾燥、悪心・嘔吐、骨髄抑制、腎障害（シスプラチン）、'
        '聴力障害（シスプラチン）</span>。'
        '<span class="kw4">経管栄養や胃瘻が一時的に必要になることがある</span>。<br>'
