        '開口障害（咀嚼筋の線維化）、下垂体機能低下症、甲状腺機能低下症、'
        '放射線性骨壊死、頸動脈狭窄、二次発癌</span>。<br>'
        '<span class="kw">治療効果と再発の監視には、'
        '内視鏡・MRI・PET-CTに加えて血漿EBV-DNA量</span>が用いられる。'
