        'A群β溶連菌・黄色ブドウ球菌など。'
        '第2〜3世代セフェム（セフトリアキソン等）の静注</span>が用いられる。'
        '<span class="kw3">Hibワクチンの普及で小児例は激減したが、'
        '成人例は減っていない</span>。<br>'
        '<span class="kw3">② 副腎皮質ステロイド</span>……'
        '<span class="kw3">浮腫の軽減を期待して併用される</span>。'
        '<span class="kw4">ただし効果発現まで時間がかかるので、'
