        '<span class="kw4">【副咽頭間隙・咽後間隙・深頸部膿瘍】</span>'
        '<span class="kw4">頸部の腫脹・発赤・可動制限、'
        '全身状態の悪化。造影CTで広がりを評価し、'
        '外切開でのドレナージが必要になることがある</span>。<br>'
        '<span class="kw4">【縦隔炎・Lemierre症候群】</span>'
        '<span class="kw4">降下性壊死性縦隔炎は致死率が高い。'
        'Lemierre症候群は内頸静脈血栓＋敗血症性肺塞栓で、'
