         '<span class="kw4">最も注意すべきは内頸動脈</span>——'
         '<span class="kw4">扁桃の外後方 約2cm のところを走っている</span>。'
         '<span class="kw4">そのため刺入は深くしすぎず（1cm程度まで）、'
         '外側ではなく内側〜正中方向へ向けて行う</span>。'
         '<span class="kw4">針にストッパー（刃先を残してカバーを付ける）を'
