         '左鎖骨上窩リンパ節が最初に腫れることがある</span>。'
         '<span class="kw3">これをVirchowリンパ節転移（Virchow徴候）</span>と呼ぶ。<br>'
         '<span class="kw">原発として頻度が高いのは、'
         '胃癌・膵癌・胆道癌・大腸癌・肺癌・食道癌・'
